/**
 * Load Google Ads event listeners
 * */

// view_item_list event
//
// Every product is detected on its own. The batcher groups them per
// conversion destination, so Google Ads receives one view_item_list with all
// items instead of one request per product.
const googleAdsViewItemListBatcher = pmw.createEventBatcher({
	label    : "Google Ads: view_item_list",
	getConfig: pmw.getViewItemListBatchConfig,
	itemKey  : item => item?.id ?? null,
	send     : (items, meta) => {
		gtag("event", "view_item_list", {...meta, items});
	},
});

pmw.bus.on("pmw:pixel:view-item-list", (payload) => {

	try {
		if (!pmw.shouldFireBrowserPixel(payload, "google_ads")) return;

		// Get Google Ads data from the unified payload structure
		const googleAdsData = payload.pixels?.google_ads;

		if (!googleAdsData?.items?.length) {
			return;
		}

		const {items, ...meta} = googleAdsData;

		pmw.gtagLoaded().then(() => {
			items.forEach(item => googleAdsViewItemListBatcher.add(JSON.stringify(meta.send_to ?? ""), item, meta));
		}).catch(pmw.gtagNotLoaded("Google Ads: view_item_list"));
	} catch (e) {
		console.error(e);
	}
});

